const t={rules:{intro:{t:0,b:{t:2,i:[{t:3}],s:"安全な「もし～なら」ルールでプリンターを自動化します。初期状態はオフ。各ルールは自分で有効化してください。"}},empty:{t:0,b:{t:2,i:[{t:3}],s:"ルールはまだありません。下から追加し、準備ができたら有効化してください。"}},engine:{on:{t:0,b:{t:2,i:[{t:3}],s:"ルールエンジンはオンです"}},off:{t:0,b:{t:2,i:[{t:3}],s:"ルールエンジンはオフです"}},turnOn:{t:0,b:{t:2,i:[{t:3}],s:"オンにする"}},turnOff:{t:0,b:{t:2,i:[{t:3}],s:"オフにする"}},masterNote:{t:0,b:{t:2,i:[{t:3}],s:"エンジンと個々のルールの両方がオンになるまで、何も実行されません。"}}},triggers:{print_complete:{t:0,b:{t:2,i:[{t:3}],s:"プリントが完了したとき"}},print_error:{t:0,b:{t:2,i:[{t:3}],s:"プリンターがエラーになったとき"}},temp_above:{t:0,b:{t:2,i:[{t:3}],s:"ヒーターが次の温度を上回ったとき"}},temp_below:{t:0,b:{t:2,i:[{t:3}],s:"ヒーターが次の温度を下回ったとき"}}},actions:{notify:{t:0,b:{t:2,i:[{t:3}],s:"通知を記録する"}},gcode:{t:0,b:{t:2,i:[{t:3}],s:"g-code コマンドを実行する"}}},rule:{armed:{t:0,b:{t:2,i:[{t:3}],s:"有効"}},arm:{t:0,b:{t:2,i:[{t:3}],s:"無効"}},edit:{t:0,b:{t:2,i:[{t:3}],s:"編集"}},delete:{t:0,b:{t:2,i:[{t:3}],s:"削除"}},confirmDelete:{t:0,b:{t:2,i:[{t:3}],s:"ルールを削除"}}},form:{name:{t:0,b:{t:2,i:[{t:3}],s:"ルール名"}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"例: プリント後にヒーターをオフ"}},trigger:{t:0,b:{t:2,i:[{t:3}],s:"もし（トリガー）"}},action:{t:0,b:{t:2,i:[{t:3}],s:"なら（アクション）"}},heater:{t:0,b:{t:2,i:[{t:3}],s:"ヒーター"}},value:{t:0,b:{t:2,i:[{t:3}],s:"温度（°C）"}},message:{t:0,b:{t:2,i:[{t:3}],s:"メッセージ"}},messagePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"ルールログに表示されます"}},gcode:{t:0,b:{t:2,i:[{t:3}],s:"G-code"}},gcodePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:"例: TURN_OFF_HEATERS"}},save:{t:0,b:{t:2,i:[{t:3}],s:"ルールを保存"}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"キャンセル"}},add:{t:0,b:{t:2,i:[{t:3}],s:"ルールを追加"}}},log:{title:{t:0,b:{t:2,i:[{t:3}],s:"最近のアクティビティ"}},outcome:{notify:{t:0,b:{t:2,i:[{t:3}],s:"通知しました"}},ran:{t:0,b:{t:2,i:[{t:3}],s:"g-code を実行しました"}},skipped_busy:{t:0,b:{t:2,i:[{t:3}],s:"スキップ（プリンター使用中）"}},error:{t:0,b:{t:2,i:[{t:3}],s:"エラー"}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"ガイド"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"ルールエンジンガイド"}},close:{t:0,b:{t:2,i:[{t:3}],s:"閉じる"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"ルールエンジンとは？"}},body:{t:0,b:{t:2,i:[{t:3}],s:"プリンターを監視し、設定した条件が満たされたときにアクションを実行します。たとえば、プリント完了時にメモを記録したり、ヒーターをオフにしたりできます。各ルールは「もし（トリガー）なら（アクション）」という形です。"}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:"安全性の仕組み"}},body:{t:0,b:{t:2,i:[{t:3}],s:"エンジンは初期状態でオフであり、すべてのルールは個別に有効化する必要があるため、予期せず実行されることはありません。ルールはその条件が初めて真になったときに一度だけ発動します。g-code アクションはプリンターがアイドル状態のときのみ実行され、プリント中は拒否されます。すべての結果はログに記録されます。"}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"用語集"}}}},glossary:{trigger:{term:{t:0,b:{t:2,i:[{t:3}],s:"トリガー"}},def:{t:0,b:{t:2,i:[{t:3}],s:"ルールを開始する条件。例: プリントの完了、またはヒーターが一定の温度を超えること。"}}},action:{term:{t:0,b:{t:2,i:[{t:3}],s:"アクション"}},def:{t:0,b:{t:2,i:[{t:3}],s:"ルールが発動したときに行う処理: 通知を記録する、または g-code コマンドを実行する（アイドル時のみ）。"}}},armed:{term:{t:0,b:{t:2,i:[{t:3}],s:"有効"}},def:{t:0,b:{t:2,i:[{t:3}],s:"オンになっているルール。無効なルールは保持されますが発動しません。"}}}}}}};export{t as default};
